"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["94767"],{13933(e){e.exports=JSON.parse('{"id":"F207","slug":"fcff","name":"Free Cash Flow to the Firm (FCFF)","subject":"Valuation","section":"Valuation","topic":"Free cash flow to firm (FCFF)","level":"Intermediate","aliases":["FCFF","unlevered free cash flow","free cash flow to firm","UFCF"],"formula":{"latex":"FCFF=EBIT(1-T)+D\\\\&A-CapEx-\\\\Delta NWC","also":[],"text":"FCFF = EBIT x (1 - T) + Depreciation and amortization - Capital expenditure - Increase in net working capital"},"symbols":[{"symbol":"FCFF","meaning":"Cash available to all providers of capital, before paying them","unit":"money"},{"symbol":"EBIT","meaning":"Earnings before interest and tax","unit":"money"},{"symbol":"T","meaning":"Tax rate, as a decimal","unit":"decimal"},{"symbol":"D&A","meaning":"Depreciation and amortization, non-cash costs added back","unit":"money"},{"symbol":"CapEx","meaning":"Money spent on long-term assets","unit":"money"},{"symbol":"Delta NWC","meaning":"Increase in net working capital","unit":"money"}],"when_to_use":"Use it as the cash flow in a DCF that is discounted at WACC. It ignores how the firm is financed, so it can be used to value the whole business.","worked_example":{"problem":"A firm has EBIT of 1,000 and a tax rate of 25%. Depreciation is 200, capital expenditure is 300 and working capital rises by 50. What is its FCFF?","inputs":{"ebit":1000,"t":25,"da":200,"capex":300,"dnwc":50},"steps":[{"label":"NOPAT = EBIT x (1 - T)","working":"1000 x (1-0.25)","value":"750.00"},{"label":"FCFF = NOPAT + D&A - CapEx - increase in NWC","working":"750+200-300-50","value":"600.00"}],"answer":"The FCFF is 600.00, which is the cash available to lenders and shareholders together."},"calculator":{"available":true,"inputs":[{"id":"ebit","label":"EBIT","unit":"money","type":"number","default":1000,"hint":""},{"id":"t","label":"Tax rate","unit":"%","type":"number","default":25,"hint":""},{"id":"da","label":"Depreciation and amortization","unit":"money","type":"number","default":200,"hint":""},{"id":"capex","label":"Capital expenditure","unit":"money","type":"number","default":300,"hint":""},{"id":"dnwc","label":"Increase in net working capital","unit":"money","type":"number","default":50,"hint":""}],"checks":[],"steps":[{"id":"nopat","label":"NOPAT = EBIT x (1 - T)","expr":"ebit*(1-t)","format":"money"},{"id":"fcff","label":"FCFF = NOPAT + D&A - CapEx - increase in NWC","expr":"nopat+da-capex-dnwc","format":"money"}],"results":["fcff"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"nopat":750,"fcff":600}},"finder":{"finds":"Cash flow available to all capital providers","needs":"EBIT, tax rate, D&A, capex, change in NWC"},"related":[{"slug":"fcfe","name":"Free Cash Flow to Equity (FCFE)"},{"slug":"dcf-enterprise-value","name":"DCF Enterprise Value (Explicit Period plus Terminal Value)"},{"slug":"project-operating-cash-flow","name":"Project Operating Cash Flow"}],"related_ids":["F208","F211","F157"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>F</mi><mi>C</mi><mi>F</mi><mi>F</mi><mo>=</mo><mi>E</mi><mi>B</mi><mi>I</mi><mi>T</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>T</mi><mo stretchy=\\"false\\">)</mo><mo>+</mo><mi>D</mi><mi mathvariant=\\"normal\\">&amp;</mi><mi>A</mi><mo>\u2212</mo><mi>C</mi><mi>a</mi><mi>p</mi><mi>E</mi><mi>x</mi><mo>\u2212</mo><mi mathvariant=\\"normal\\">\u0394</mi><mi>N</mi><mi>W</mi><mi>C</mi></mrow><annotation encoding=\\"application/x-tex\\">FCFF=EBIT(1-T)+D\\\\&amp;A-CapEx-\\\\Delta NWC</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"fcfe","name":"Free Cash Flow to Equity (FCFE)"},"next":{"slug":"free-cash-flow-conversion","name":"Free Cash Flow vs. Net Income"},"lesson":null,"total":522}')}}]);